package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 998244353
const MAX_S = 5000
const MAX_P = 100

func addMod(a, b int) int {
	s := a + b
	if s >= MOD {
		s -= MOD
	}
	return s
}

func subMod(a, b int) int {
	s := a - b
	if s < 0 {
		s += MOD
	}
	return s
}

func mulMod(a, b int) int {
	return int((int64(a) * int64(b)) % MOD)
}

func powMod(a, e int) int {
	res := 1
	for e > 0 {
		if e&1 == 1 {
			res = mulMod(res, a)
		}
		a = mulMod(a, a)
		e >>= 1
	}
	return res
}

func invMod(a int) int {
	return powMod(a, MOD-2)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var p, s, r int
	fmt.Fscan(reader, &p, &s, &r)

	// Precompute factorials and inverse factorials up to MAX_S + MAX_P
	maxN := MAX_S + MAX_P + 5
	fact := make([]int, maxN)
	invFact := make([]int, maxN)
	fact[0] = 1
	for i := 1; i < maxN; i++ {
		fact[i] = mulMod(fact[i-1], i)
	}
	invFact[maxN-1] = invMod(fact[maxN-1])
	for i := maxN - 2; i >= 0; i-- {
		invFact[i] = mulMod(invFact[i+1], i+1)
	}

	// Binomial coefficient function
	C := func(n, k int) int {
		if k < 0 || k > n {
			return 0
		}
		return mulMod(fact[n], mulMod(invFact[k], invFact[n-k]))
	}

	// ways(t, m, n): number of ways to distribute sum n among m players,
	// each scoring between 0 and t inclusive.
	ways := func(t, m, n int) int {
		if n < 0 {
			return 0
		}
		if t < 0 {
			if n == 0 && m == 0 {
				return 1
			}
			return 0
		}
		res := 0
		maxK := m
		if t+1 > 0 {
			maxK = n / (t + 1)
			if maxK > m {
				maxK = m
			}
		}
		for k := 0; k <= maxK; k++ {
			rem := n - k*(t+1)
			term := mulMod(C(m, k), C(rem+m-1, m-1))
			if k%2 == 1 {
				res = subMod(res, term)
			} else {
				res = addMod(res, term)
			}
		}
		return res
	}

	// Count number of states where Hasan wins (numerator)
	ansNum := 0
	for a1 := r; a1 <= s; a1++ {
		remSum := s - a1
		// Case 1: Hasan's score strictly greater than all others
		// Others score at most a1 - 1
		case1 := ways(a1-1, p-1, remSum)

		// Case 2: Tie with some other players
		// At least one other player scores exactly a1
		case2 := 0
		for k := 1; k <= p-1; k++ {
			sumNeeded := remSum - k*a1
			if sumNeeded < 0 {
				break
			}
			// Choose which k players tie with Hasan
			choose := C(p-1, k)
			// Remaining p-1-k players score at most a1-1
			w := ways(a1-1, p-1-k, sumNeeded)
			waysTie := mulMod(choose, w)
			// Probability Hasan wins among k+1 tied players
			probWin := invMod(k + 1)
			waysTie = mulMod(waysTie, probWin)
			case2 = addMod(case2, waysTie)
		}

		ansNum = addMod(ansNum, addMod(case1, case2))
	}

	// Total number of states (denominator): a1 >= r, sum = s
	// Equivalent to ways(s-r, p-1, s-r)? No.
	// a1 >= r, a2..ap >= 0, sum a_i = s
	// Let a1' = a1 - r >= 0. Sum a1' + a2 + ... + ap = s - r.
	// Number of solutions: C((s-r) + p - 1, p - 1)
	den := C(s-r+p-1, p-1)

	ans := mulMod(ansNum, invMod(den))
	fmt.Println(ans)
}
